'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/'),U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output');fs.mkdirSync(OUT,{recursive:true});const OWNER='p14_owner_260804221827';
function rc(){const e=process.env.P11_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function sa(){return rc().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function lt(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(500);ok=!/\/login(?:[/?#]|$)/i.test(p.url())}catch{}return{ok,c,p}}
function cs(t,v){const a=[...v];for(const m of String(t).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==OWNER&&!x.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(x))}
async function owner(b){const s=sa(),x=await lt(b,s.username,s.password);await x.p.goto(U('superadmin/companies/27/users'),{waitUntil:'domcontentloaded'});const f=x.p.locator('form[action$="/superadmin/companies/27/owner/reset-password"]'),n=x.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await n;const v=await x.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(n=>n.value||n.textContent||'').filter(Boolean)),a=cs(await x.p.locator('body').innerText(),v);await x.c.close();for(const q of a){const y=await lt(b,OWNER,q);if(y.ok)return y;await y.c.close()}throw Error('owner unavailable')}
(async()=>{const r={status:'FAIL',form:null,controls:[],error:null};let b,o;try{b=await chromium.launch({headless:true});o=await owner(b);const p=o.p;await p.goto(U('company/vehicle-sets'),{waitUntil:'domcontentloaded'});await p.locator('button,a').filter({hasText:/Добавить|Создать/i}).first().click();await p.waitForTimeout(400);const f=p.locator('#vehicle-set-create-form');await f.locator('[name="set_type"]').selectOption('single');await p.waitForTimeout(600);r.form=await f.evaluate(x=>({outerHTML:x.outerHTML.slice(0,30000),valid:x.checkValidity(),action:x.action,method:x.method}));r.controls=await p.evaluate(()=>[...document.querySelectorAll('button,input[type="submit"],input[type="button"],a.btn')].filter(e=>{const s=getComputedStyle(e),b=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&b.width>1&&b.height>1}).map(e=>({tag:e.tagName,text:(e.textContent||e.value||'').trim().replace(/\s+/g,' ').slice(0,160),type:e.type||null,id:e.id||null,cls:e.className||null,form:e.getAttribute('form'),onclick:e.getAttribute('onclick'),html:e.outerHTML.slice(0,1200)})));await p.screenshot({path:path.join(OUT,'P14_VEHICLE_SAVE_DISCOVERY_1920x1080.png'),fullPage:false});r.status='PASS'}catch(e){r.error={name:e?.name||'Error',message:String(e?.message||e).slice(0,500)}}finally{if(o?.c)await o.c.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P14_runtime_result.json'),JSON.stringify(r,null,2));console.log(`P14_VEHICLE_SAVE_DISCOVERY=${r.status}`);process.exitCode=r.status==='PASS'?0:1}})();
